import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>الزوايا المستديرة تلطف الصورة. فهي تحول مستطيلاً صلباً إلى شكل لطيف يناسب الشاشات الحديثة والبطاقات والصور الرمزية.</p>\n<p>واليوم تستخدم كل التطبيقات والمواقع زوايا مستديرة. فصور الملف الشخصي دوائر، والبطاقات حوافها ناعمة، والأزرار على شكل حبوب، لذا تبدو الصور ذات الزوايا المستديرة في مكانها.</p>\n<p>يشرح هذا الدليل كيفية عمل تدوير الزوايا، وأي الأشكال تختار، وكيفية تصدير النتيجة بشكل صحيح. ويغطي نصف القطر، والتحكم بكل زاوية، والشفافية، والصيغ.</p>\n<p>ويمكنك تجربة كل شكل في هذا الدليل مجاناً في المتصفح باستخدام <a href=\"/ar/tadweer-zawaya-as-sura/\">أداة تدوير زوايا الصورة</a>، التي تدور الزوايا الأربع أو كل واحدة على حدة وتصدر بصيغة PNG شفافة.</p>\n<h2 id=\"what-rounding-does\">ماذا يفعل تدوير الزوايا فعلاً؟</h2>\n<p>عند التدوير تقص زوايا صورة على منحنى. فتبقى الحواف المستقيمة، لكن الزوايا الحادة 90 درجة تتحول إلى أقواس ناعمة.</p>\n<p>ويحدد المنحنى قيمة نصف قطر. فنصف قطر صغير يعطي تنعيماً خفيفاً، بينما نصف قطر كبير يحول الزوايا إلى منحنيات عميقة تغير الشكل كله.</p>\n<p>ولا يغير التدوير بكسلات داخل الصورة. فهو يزيل فقط مناطق الزوايا، فتبقى الصورة حادة تماماً كما في الأصل.</p>\n<p>وما يتغير هو شكل الملف. فصورة مستديرة الزوايا لم تعد مستطيلاً، ويجب أن تكون الزوايا شفافة أو مملوءة بلون صلب.</p>\n<h2 id=\"radius-explained\">نصف قطر الزاوية، مشروحاً</h2>\n<p>يقاس نصف القطر بالبكسلات، وتعرض الأداة القيمة حية أثناء ضبطها. فنصف قطر أكبر يعني زاوية أكثر استدارة.</p>\n<p>ونصف قطر صغير، من 10 إلى 20 بكسلاً، يلطف الزوايا بالقدر الكافي لملاحظته. وهو مناسب للبطاقات والمصغرات ولقطات الشاشة، حيث يجب أن يكون التدوير خفيفاً.</p>\n<p>ونصف قطر متوسط، من 50 إلى 100 بكسل، يعطي مظهراً مستديراً واضحاً. وهو مناسب للصور الرمزية والمنشورات الاجتماعية ورسوم التطبيقات، حيث يكون الشكل جزءاً من التصميم.</p>\n<p>أما نصف القطر الكبير جداً فيحول الصورة إلى دائرة أو حبة. وهذا تغيير شكل مقصود، لا تنعيم خفيف، وهو مناسب لصور الملف الشخصي والشارات.</p>\n<h2 id=\"per-corner-control\">التحكم بكل زاوية: تدوير زاوية واحدة في كل مرة</h2>\n<p>تحتاج معظم الصور إلى الزوايا الأربع مستديرة بالتساوي، لكن بعض التصاميم تحتاج زاوية أو زاويتين فقط. فبطاقة مدونة مثلاً قد تكون زاويتاها العلويتان مستديرتين والسفليتان مربعتين.</p>\n<p>ويتيح وضع كل زاوية تحديد نصف قطر مختلف لكل زاوية. فيمكنك تدوير الزاويتين العلويتين وترك السفليتين مربعتين، أو تدوير زاوية واحدة لتأثير خاص.</p>\n<p>وعند إيقاف وضع كل زاوية، تعود إلى نصف قطر واحد لكل الزوايا. وتبقى القيم الفردية محفوظة أثناء إيقاف الوضع، فيمكنك إعادة تشغيله دون فقدان إعداداتك.</p>\n<p>واستخدم التحكم بكل زاوية باعتدال. فتصميم فيه أربعة أنصاف أقطار مختلفة يبدو حادثاً، بينما زاوية أو زاويتان مستديرتان والباقي مربع يبدو مقصوداً.</p>\n<h2 id=\"full-circle-pill\">دائرة كاملة وشكل حبة</h2>\n<p>اختصار الدائرة الكاملة يحول صورة مربعة إلى دائرة مثالية. فهو يثبت نصف القطر عند نصف حجم الصورة، فتنحني الزوايا حتى تغلق الدائرة.</p>\n<p>وفي صورة مستطيلة، يصنع الاختصار نفسه شكل حبة: مستطيل نهايتاه مستديرتان تماماً. وتناسب الحبوب الأزرار والشارات واللافتات.</p>\n<p>ولدائرة نظيفة، ابدأ بصورة مربعة. قص الصورة بنسبة 1:1 أولاً، ثم طبق اختصار الدائرة الكاملة وستكون النتيجة صورة رمزية مستديرة تماماً.</p>\n<p>وراجع النتيجة في صورة مستطيلة قبل تأكيدها. فشكل الحبة قد يبدو أنيقاً، لكنه قد يقص أيضاً محتوى مهماً على الجانبين.</p>\n<h2 id=\"transparent-vs-solid-fill\">تعبئة شفافة أم صلبة في الزوايا</h2>\n<p>عند قص الزوايا، يجب ملء المساحة الفارغة بشيء. وتوفر الأداة خيارين: شفافة، تترك الزوايا شفافة، أو لون صلب.</p>\n<p>والزوايا الشفافة هي الخيار الصحيح لرسوم الويب والصور الرمزية والتراكبات. فتندمج الصورة مع أي خلفية، لأن الزوايا تعرض ما خلف الصورة.</p>\n<p>أما التعبئة الصلبة فهي الخيار الصحيح عندما لا تدعم الوجهة الشفافية. فلون صلب، مثل الأبيض، يملأ الزوايا فتبدو الصورة مستطيلاً بحواف ناعمة.</p>\n<p>وإذا اخترت الشفافية مع تحديد JPG، تتغير الصيغة تلقائياً. فـ JPG لا شفافية فيه، لذا تنقلها الأداة إلى PNG أو WebP للحفاظ على الزوايا شفافة.</p>\n<h2 id=\"formats-png-webp-jpg\">الصيغ: PNG وWebP وJPG</h2>\n<p>تدعم PNG وWebP الشفافية، فتحافظان على الزوايا المستديرة شفافة. وهما الصيغتان المناسبتان للصور الرمزية والشعارات وأي رسم يقع فوق خلفية ملونة.</p>\n<p>أما JPG فلا شفافية فيه، فالزوايا المستديرة المصدرة بصيغة JPG تبقى بتعبئة صلبة. وتصبح الزوايا بلون صلب، عادة أبيض، يبدو جيداً على خلفية بيضاء.</p>\n<p>ولرسوم الويب، غالباً ما تكون WebP الخيار الأفضل. فهي تعطي ملفات أصغر من PNG بالشفافية نفسها، مع أن بعض الأنظمة القديمة ما زالت ترفض الصيغة.</p>\n<p>ولأنظف نتيجة، اختر PNG. فهي دون فقدان، فتبقى الحواف المنحنية ناعمة، وتعمل في كل مكان، بما فيه المتصفحات القديمة وتطبيقات المراسلة.</p>\n<h2 id=\"rounding-for-avatars\">تدوير الزوايا للصور الرمزية وصور الملف الشخصي</h2>\n<p>الصور الرمزية دائرية أو مستديرة الزوايا تقريباً دائماً. فصورة مربعة بزوايا مستديرة تبدو حديثة، بينما مربعة بزوايا حادة تبدو ملفاً غير معدل.</p>\n<p>قص الصورة إلى مربع أولاً ثم دوّر الزوايا. فقص 1:1 مع نصف قطر كبير يعطي دائرة نظيفة، وهي الشكل القياسي للصورة الرمزية.</p>\n<p>وأبقِ الوجه داخل الإطار جيداً. فالزوايا تقص، لذا قد يفقد وجه قريب من الحافة أذناً أو جزءاً من الشعر بسبب المنحنى.</p>\n<p>وصدر الصور الرمزية بصيغة PNG أو WebP. فالشفافية تبقي الزوايا شفافة، فتندمج الصورة الرمزية مع أي خلفية ملف شخصي، فاتحة أو داكنة.</p>\n<h2 id=\"rounding-for-cards\">تدوير الزوايا للبطاقات ورسوم الواجهة</h2>\n<p>البطاقات هي لبنات بناء الواجهات الحديثة، وزواياها مستديرة تقريباً دائماً. فصورة بزوايا مستديرة مطابقة تناسب تماماً داخل بطاقة.</p>\n<p>وطابق نصف قطر الصورة مع نصف قطر البطاقة. فصورة بنصف قطر 16 بكسلاً داخل بطاقة بنصف قطر 16 بكسلاً تبدو مثالية، بينما الأنصاف المختلفة تبدو غير متناسقة.</p>\n<p>ولبطاقة مدونة، دوّر الزاويتين العلويتين واترك السفليتين مربعتين. فالصورة في أعلى البطاقة، والجزء السفلي المربع يتماشى مع النص أسفلها.</p>\n<p>وأبقِ نصف القطر ثابتاً في كل بطاقات المجموعة. فشبكة بطاقات بزوايا متطابقة تبدو احترافية، بينما الأنصاف المختلطة تبدو عشوائية.</p>\n<h2 id=\"smooth-edges\">لماذا تبدو الحواف المنحنية ناعمة لا مسننة؟</h2>\n<p>الحافة المنحنية على الشاشة مصنوعة من بكسلات مربعة، لذا ينبغي أن تبدو مسننة. وعملياً تبدو ناعمة، لأن الأداة تمزج بكسلات الحافة مع لون الخلفية.</p>\n<p>ويسمى هذا المزج تنعيم الحواف (antialiasing). فالبكسلات على المنحنى شفافة جزئياً، ما يخدع العين لترى خطاً ناعماً بدلاً من درج.</p>\n<p>ويعمل تنعيم الحواف أفضل على خلفية شفافة. فالبكسلات الممزوجة تتلاشى في ما خلف الصورة، فتبدو المنحنى نظيفة على أي لون.</p>\n<p>ومع تعبئة صلبة، يكون المزج أقل مرونة. فبكسلات الحافة تمزج مع لون التعبئة، فتبدو المنحنى ناعمة على ذلك اللون لكنها خشنة على أي لون آخر.</p>\n<h2 id=\"rounding-and-print\">تدوير الزوايا للطباعة</h2>\n<p>نادراً ما تكون للصور المطبوعة زوايا مستديرة، لأن قص مطبوعة على منحنى عمل إضافي. فصورة رقمية مستديرة الزوايا، مطبوعة على ورق مستطيل، ستعرض الزوايا بتعبئة.</p>\n<p>وإذا طبعت صورة مستديرة الزوايا، اختر تعبئة صلبة تطابق الورق. فتعبئة بيضاء على ورق أبيض تبدو كصورة مستديرة، بينما تصدير شفاف مطبوع قد يخرج بخلفية غير متوقعة.</p>\n<p>أما للملصقات والعلامات، فالزوايا المستديرة هي المهمة. فملصق بزوايا مستديرة ينزع نظيفاً ويبدو مكتملاً، بينما ملصق بزوايا حادة قد يعلق وينتزع.</p>\n<p>وراجع حجم الطباعة قبل التدوير. فنصف قطر صغير في طباعة كبيرة قد يكون غير مرئي، بينما نصف قطر كبير في طباعة صغيرة قد يهيمن على الشكل.</p>\n<h2 id=\"rounding-vs-cropping\">التدوير أم القص: عملان مختلفان</h2>\n<p>يزيل القص بكسلات من الحواف لتغيير التأطير، بينما يزيل التدوير الزوايا فقط لتغيير الشكل. وهما يحلان مشكلتين مختلفتين.</p>\n<p>قص عندما يكون التأطير خاطئاً: سماء زائدة، أو غريب على الحافة، أو موضوع صغير جداً. فالتدوير لا يستطيع إصلاح التأطير.</p>\n<p>ودوّر عندما يكون الشكل خاطئاً: مستطيل حاد يبدو قاسياً في واجهة حديثة. فالقص لا يستطيع تنعيم زاوية.</p>\n<p>واستخدم الاثنين معاً عندما تحتاج صورة إلى تأطير وشكل. قص أولاً لإصلاح التكوين ثم دوّر زوايا النتيجة المقصوصة لتناسب وجهتها.</p>\n<h2 id=\"rounding-and-borders\">تدوير الزوايا وإضافة حدود</h2>\n<p>الزوايا المستديرة والحدود تتناسبان جيداً. فحد رفيع بنصف قطر مطابق يصنع مظهر بطاقة يناسب المنشورات الاجتماعية والعروض التقديمية وصور المنتجات.</p>\n<p>وطابق نصف قطر الحد مع نصف قطر الزاوية. فحد بنصف قطر 16 بكسلاً حول صورة بنصف قطر 16 بكسلاً يبدو مثالياً، بينما الأنصاف المختلفة تبدو غير متناسقة.</p>\n<p>ودوّر الزوايا أولاً ثم أضف الحد. فأداة الحدود تقرأ شكل الصورة، لذا يبقي التدوير أولاً الإطار محاذياً للمنحنيات.</p>\n<p>ولأسلوب بولارويد، أبقِ الزوايا مربعة. فالمظهر الكلاسيكي للفيلم الفوري فيه زوايا حادة، وتدويرها يكسر الطابع القديم.</p>\n<h2 id=\"rounding-on-mobile\">تدوير الزوايا على الهاتف أو الجهاز اللوحي</h2>\n<p>تعمل الأداة على شاشات اللمس، فيمكنك تدوير صورة على الهاتف نفسه الذي التقطتها به. ارفع الصورة من معرضك، واسحب عنصر تحكم نصف القطر، ونزل النتيجة.</p>\n<p>واستخدم اختصار الدائرة الكاملة للصور الرمزية على شاشة صغيرة. فلمسة واحدة تحول صورة مربعة إلى دائرة، أسرع من سحب عنصر التحكم إلى القيمة الدقيقة.</p>\n<p>وراجع المعاينة بحجم كامل قبل التنزيل. فنصف قطر يبدو خفيفاً على شاشة الهاتف الصغيرة قد يبدو أوضح عند مشاهدته على حاسوب.</p>\n<p>وتحفظ الملفات المنزلة في مجلد التنزيلات المعتاد. ومن هناك يمكنك تعيين الصورة المستديرة الزوايا كصورة ملف شخصي أو مشاركتها مباشرة.</p>\n<h2 id=\"privacy-local-processing\">الخصوصية: تدوير دون رفع أي شيء</h2>\n<p>يحدث تدوير الزوايا كله في متصفحك. فصورك لا ترفع إلى أي خادم أبداً، وهذا مهم عندما تكون الصور صوراً شخصية أو عمل عملاء.</p>\n<p>وهذه ميزة حقيقية أمام محررات السحابة. فصورة ملف شخصي أو صورة عائلية لا ينبغي أن تسافر إلى خادم لا تراه لمجرد تنعيم زواياها.</p>\n<p>كما تزيل الأداة بيانات GPS في EXIF عند التصدير. فصورة مستديرة الزوايا منزلة من الأداة لا تحتفظ بأي سجل لمكان التقاطها.</p>\n<p>واحتفظ بالصورة الأصلية دون تدوير. فبمجرد قص الزوايا في تصدير، لا يمكن استعادتها من ذلك الملف، فالأصل هو نسختك الكاملة الوحيدة.</p>\n<h2 id=\"common-rounding-mistakes\">أخطاء شائعة عند تدوير الزوايا</h2>\n<p>الخطأ الأكثر شيوعاً هو التصدير بصيغة JPG وتوقع الشفافية. فـ JPG لا شفافية فيه، فتبقى الزوايا بتعبئة صلبة، تبدو سيئة على خلفية ملونة.</p>\n<p>وخطأ آخر هو نصف قطر كبير جداً للصورة. فصورة صغيرة بنصف قطر هائل تتحول إلى دائرة عندما كان المطلوب فقط تدويراً خفيفاً.</p>\n<p>كما ينسى الناس القص إلى مربع قبل صنع دائرة. فصورة مستطيلة مع اختصار الدائرة الكاملة تتحول إلى حبة، لا دائرة، وقد لا تناسب المكان المقصود.</p>\n<p>وأخيراً، لا تدور JPG نفسه مراراً وتكراراً. فكل حفظ يضيف ضرراً، لذا عد دائماً إلى الملف الأصلي عندما تريد نصف قطر مختلفاً.</p>\n<h2 id=\"rounding-workflow\">سير عمل يحافظ على التدوير نظيفاً</h2>\n<p>ابدأ بالملف الأصلي وقرر الوجهة أولاً. فصورة رمزية وبطاقة وملصق تحتاج أشكالاً مختلفة، لذا يقرر نصف القطر قبل التدوير.</p>\n<p>وقص إلى الشكل الصحيح قبل التدوير. فقص مربع لدائرة، وقص عريض لحبة، وقص بطاقة لصورة مدونة تبدأ كلها بالقصاص.</p>\n<p>وراجع النتيجة المستديرة بحجم كامل قبل التنزيل. واقترب من الزوايا وتأكد أن المنحنيات ناعمة وأنه لم يقص شيء مهم.</p>\n<p>واحفظ الملف المستدير باسم واضح، مثل avatar-circle.png. فقد تحتاج الشكل نفسه مجدداً، والاسم الواضح يوفر عليك إعادة العمل.</p>\n<h2 id=\"rounding-for-stickers\">تدوير الزوايا للملصقات والعلامات</h2>\n<p>تبدو الملصقات والعلامات أفضل بزوايا مستديرة. فملصق بزوايا مستديرة ينزع نظيفاً ويبدو مكتملاً، بينما ملصق بزوايا حادة قد يعلق وينتزع.</p>\n<p>واستخدم نصف قطر متوسطاً للملصقات، كبيراً بما يكفي ليظهر وصغيراً بما يكفي للحفاظ على التصميم سليماً. فنصف قطر كبير جداً قد يقطع النص أو الرسم.</p>\n<p>وصدر الملصقات بصيغة PNG أو WebP للحفاظ على الزوايا شفافة. فسيوضع الملصق على أي خلفية، من غطاء حاسوب محمول إلى غلاف دفتر، دون صندوق أبيض.</p>\n<p>وجرب الملصق بحجمه الحقيقي قبل الطباعة. فنصف قطر يبدو جيداً على الشاشة قد يكون غير مرئي في ملصق صغير، أو قد يهيمن على ملصق كبير.</p>\n<p>وللعملية خطوة بخطوة، راجع <a href=\"/ar/blog/kayfiyya-tadweer-zawaya-as-sura/\">كيفية تدوير زوايا صورة</a>. وللمقارنة، اقرأ <a href=\"/ar/blog/zawaya-mudawwara-vs-qass-dairi/\">زوايا مستديرة أم قص دائري: الصور الرمزية والبطاقات</a>، ولتأطير صورة مستديرة الزوايا، استخدم <a href=\"/ar/idafa-itar-ila-as-sura/\">مولد الحدود للصور</a>.</p>";

